const $=s=>document.querySelector(s);
    const archetypes={wanderer:{label:'Wayfarer',desc:'A patient traveler who notices what others miss.',stats:{might:410,grace:540,wit:600,heart:450}},duelist:{label:'Moonblade',desc:'A quick-handed fighter with a promise to keep.',stats:{might:610,grace:620,wit:420,heart:390}},oracle:{label:'Shrine-touched',desc:'A soft-spoken listener to the unseen.',stats:{might:380,grace:440,wit:610,heart:630}}};
    const qualities={bright:{label:'Bright-eyed',desc:'Hope comes easily, even here.',mod:{heart:55,wit:25}},guarded:{label:'Guarded',desc:'You trust your own instincts first.',mod:{grace:45,might:25}},wry:{label:'Wry',desc:'A crooked smile is your favorite armor.',mod:{wit:35,heart:35}}};
    const statNames={might:'Might',grace:'Grace',wit:'Insight',heart:'Spirit'};
    const state={started:false,name:'',archetype:'wanderer',quality:'bright',base:{},gear:{weapon:null,charm:null,coat:null},scene:'gate',step:0,log:[],ending:false};
    const items={moonsteel:{name:'Moonsteel Tanto',icon:'🗡',slot:'weapon',bonus:{might:90,grace:35},reaction:'The cool hilt settles into your palm. Your brows lift; then your mouth sets in a small, fearless line. The blade catches your reflection—and your eyes look a little more certain.'},bell:{name:'Foxfire Bell',icon:'🔔',slot:'charm',bonus:{heart:75,wit:55},reaction:'The tiny bell warms against your throat. You blink at its soft blue glow, and a surprised, almost shy smile slips across your face.'},mantle:{name:'Mothwing Mantle',icon:'🧥',slot:'coat',bonus:{grace:80,heart:30},reaction:'The mantle spills over your shoulders like midnight silk. You turn once, testing its weight; your cheeks pink, and an impressed grin wins out.'},oni:{name:'Oni-Bone Guard',icon:'🛡',slot:'coat',bonus:{might:80,heart:40},reaction:'The lacquered guard clicks into place. You wince at the weight, then meet your own gaze with a stubborn little smirk.'}};
    const scenes={
      gate:{chapter:'Prologue · The Last Train',eyebrow:'01 / The threshold',title:'Where the moon has fallen',art:'☾',text:`The last train leaves you at <em>Tsukigane Station</em>, a village erased from every map. Above the cedar roofs, the moon hangs cracked like porcelain. Its missing shard is said to sleep beneath the old mountain shrine.\n\nAt the forest’s edge, a stone stairway descends into the dark. Your <strong>first step</strong> will tell the dungeon what kind of soul has come knocking.`,choices:[{text:'Study the old warding marks before you descend.',hint:'Insight check',stat:'wit',pass:'The faded strokes resolve into a map. You spot a safe passage—and an offering left for a careful guest.',fail:'The ink shifts when you stare at it. You choose a path by instinct, and the trees seem to lean closer.',next:'shrine',gain:'bell',roll:true},{text:'Take the steps two at a time; hesitation is its own trap.',hint:'Grace check',stat:'grace',pass:'You slip past the first snare as if the shadows had held the door for you.',fail:'A thread catches your ankle. You land hard, but a quick roll keeps the fall from doing worse.',next:'shrine',roll:true}]},
      shrine:{chapter:'Act I · The listening dark',eyebrow:'02 / The offering hall',title:'A bell with no clapper',art:'⛩',text:`A fox shrine stands in a flooded chamber. Three paper lanterns burn with blue flame, though no wick remains. At its feet rests a tiny silver bell.\n\nFrom somewhere behind the altar, a child hums the tune playing on your old station’s departure board. The melody ends on a note that feels like a question.`,choices:[{text:'Offer a memory, and take the bell in return.',hint:'Accept the foxfire bell',stat:'heart',pass:'A warm light blooms in the fox’s stone eyes. The hum becomes a quiet thank-you.',fail:'The memory slips away before you can name it. The shrine accepts the silence anyway.',next:'guardian',item:'bell',bonus:true},{text:'Bow to the shrine, then follow the sound beyond it.',hint:'Spirit check',stat:'heart',pass:'The fox bows back. Somewhere ahead, a door unlocks with a soft chime.',fail:'The lantern flames gutter. You leave with the uneasy feeling that something followed.',next:'guardian',roll:true}]},
      guardian:{chapter:'Act I · The listening dark',eyebrow:'03 / The paper garden',title:'A hundred watching eyes',art:'狐',text:`Paper foxes stir among the bamboo. Their painted eyes turn toward you all at once. One steps forward, wearing a little red scarf.\n\nIt speaks with the voice of someone you almost remember: <em>“The mountain is hungry. What will you feed it?”</em> The foxes begin to circle.`,choices:[{text:'Hold your ground. The mountain can wait its turn.',hint:'Might check',stat:'might',pass:'Your steady stance makes the foxes hesitate. The red-scarved one lowers its head in respect.',fail:'The swarm knocks you back. Still, you rise before they can decide what to do with you.',next:'armory',roll:true},{text:'Answer with the station’s forgotten departure song.',hint:'Insight check',stat:'wit',pass:'The foxes join the melody. The paper garden parts like a curtain.',fail:'Your voice catches on the last note. The foxes part anyway—though one keeps your shadow.',next:'armory',roll:true}]},
      armory:{chapter:'Act II · The hollow mountain',eyebrow:'04 / The moonlit forge',title:'A blade that remembers',art:'⚔',text:`Beyond the garden, a smithy glows beneath a ceiling of black glass. No smith is there—only a single short blade laid across an anvil. Silver veins shimmer along its edge.\n\nThe weapon’s reflection doesn’t match your movement. It gives you a little nod.`,choices:[{text:'Take the blade. You have a feeling it chose you first.',hint:'Equip Moonsteel Tanto',stat:'grace',pass:'The blade hums in your hand, light as a promise.',fail:'It is heavier than it looks, but your grip steadies as the silver veins wake.',next:'crossroads',item:'moonsteel',bonus:true},{text:'Ask the empty forge what it wants from you.',hint:'Spirit check',stat:'heart',pass:'A voice in the coals asks only that you remember its name: Akari.',fail:'The coals cool. You find a sharp little knife wrapped in a smith’s cloth.',next:'crossroads',item:'moonsteel',roll:true}]},
      crossroads:{chapter:'Act II · The hollow mountain',eyebrow:'05 / The split in the path',title:'Two ways through the dark',art:'鳥',text:`The tunnel forks around an underground lake. On one side, a rope bridge sways above a starless drop. On the other, a narrow passage exhales a steady, warm wind.\n\nA line of tiny footprints leads to the bridge. They stop halfway across.`,choices:[{text:'Cross the bridge, keeping your eyes on the far shore.',hint:'Grace check',stat:'grace',pass:'You move with the ropes, not against them. The dark below never gets a chance to learn your name.',fail:'A plank gives way. You catch the rope with both hands and haul yourself up, breathless.',next:'veil',roll:true},{text:'Follow the warm wind into the narrow passage.',hint:'Insight check',stat:'wit',pass:'You find a hidden stair and a mantle folded in a dry alcove.',fail:'The passage loops back on itself, but a hidden alcove holds a dark, beautiful mantle.',next:'veil',roll:true,item:'mantle',bonus:true}]},
      veil:{chapter:'Act II · The hollow mountain',eyebrow:'06 / The memory lake',title:'The face beneath the water',art:'◌',text:`Across the lake, a pale figure waits in the mist. Its face is yours, except for the thin crack of moonlight running from temple to chin.\n\nIt asks: <em>“If the world forgets you, what should remain?”</em> Beneath the water, something bright answers with a pulse.`,choices:[{text:'Reach into the water and take the light.',hint:'Spirit check · possible relic',stat:'heart',pass:'The lake gives up a small moon-shard. Its warmth gathers around you like a second heartbeat.',fail:'The cold steals your breath, but your fingers close around a glowing shard.',next:'sanctum',item:'bell',roll:true},{text:'Tell your reflection the truth you have never said aloud.',hint:'Insight check',stat:'wit',pass:'The cracked reflection smiles. A pale foxfire pools in your palm.',fail:'The reflection turns away. The foxfire still finds its way to your hand.',next:'sanctum',item:'bell',roll:true}]},
      sanctum:{chapter:'Act III · The name of the moon',eyebrow:'07 / The sealed sanctum',title:'A gate made of rain',art:'鳥居',text:`The final gate is built from falling water. Behind it waits a vast silhouette, crowned with antlers of broken moonlight. A discarded guard’s coat lies beside the threshold, still warm.\n\nThe figure speaks your name—perfectly, though you have not said it aloud in this place.`,choices:[{text:'Wrap yourself in the guard’s lacquered coat and step through.',hint:'Equip Oni-Bone Guard',stat:'might',pass:'The coat’s old owner stands a little taller in your memory.',fail:'The buckles fight you, then click shut. The coat is yours now.',next:'heart',item:'oni',bonus:true},{text:'Slip through the water-gate before it can finish speaking.',hint:'Grace check',stat:'grace',pass:'You’re through before the last syllable leaves its mouth.',fail:'The water closes around you like a curtain. You push through, soaked but whole.',next:'heart',roll:true}]},
      heart:{chapter:'Finale · The hollow bell',eyebrow:'08 / The heart of the mountain',title:'The moon-eater',art:'☯',text:`At the mountain’s heart, the silhouette resolves into a great white wolf. A missing moon-shard glows between its teeth. Its eyes are tired, not cruel.\n\n<em>“The village gave me their grief,”</em> it says. <em>“I kept it safe. Now I cannot put it down.”</em> The air trembles. Your answer will become the ending of this story.`,choices:[{text:'Meet its gaze and ask it to share the burden.',hint:'Spirit · compassionate ending',stat:'heart',pass:'You hold out your hand. The wolf lowers its head, and the moon remembers how to be whole.',fail:'Your voice shakes, but the wolf hears the kindness beneath it. The shard begins to glow.',next:'ending',roll:true,ending:'mercy'},{text:'Draw your weapon. Free the shard, even if it must hurt.',hint:'Might · resolute ending',stat:'might',pass:'Moonsteel sings. The wolf yields the shard—not defeated, but finally released.',fail:'The blow glances aside. The wolf sees your resolve and lets the shard fall between you.',next:'ending',roll:true,ending:'resolve'},{text:'Ring the foxfire bell and sing the station’s last song.',hint:'Insight · secret ending',stat:'wit',pass:'The bell and your voice find the lost note. The wolf remembers the way home.',fail:'The first notes are ragged. Then the mountain sings with you, and the wolf remembers.',next:'ending',roll:true,ending:'secret'}]}
    };

