function startGame(){state.name=$('#hero-name').value.trim().slice(0,20)||'Aoi';state.base={...archetypes[state.archetype].stats};const q=qualities[state.quality].mod;Object.keys(q).forEach(k=>state.base[k]+=q[k]);state.started=true;state.step=0;state.scene='gate';state.log=[];state.gear={weapon:null,charm:null,coat:null};state.ending=false;state.mood='calm';addLog(`${state.name} descended toward the hollow mountain.`);save();render()}
function statMarkup(){const values=effective();return Object.entries(statNames).map(([key,label])=>`<div class="stat"><div class="stat-top"><span class="stat-name">${label}</span><span class="stat-value">${values[key]}<span style="color:#747885"> / 999</span></span></div><div class="stat-track"><div class="stat-fill" style="width:${Math.max(3,values[key]/999*100)}%"></div></div></div>`).join('')}
function gearMarkup(){const slots=[['weapon','⚔','Weapon'],['charm','✧','Charm'],['coat','◈','Outerwear']];return slots.map(([key,icon,label])=>{const item=state.gear[key];return `<div class="equip-row"><span class="equip-icon">${item?item.icon:icon}</span><div class="equip-meta"><div class="equip-slot">${label}</div><div class="equip-name ${item?'':'empty-equip'}">${item?esc(item.name):'Nothing equipped'}</div></div></div>`}).join('')}
function layout(content){return `<div class="shell"><header class="topbar"><div class="brand"><span class="brand-mark">☾</span> MOONFALL <span style="color:#747784;font-weight:400">/ TEXT ADVENTURE</span></div><div class="edition">A LITTLE STORY ABOUT WHAT WE CARRY</div><div class="top-actions"><button class="quiet-btn" onclick="openJournal()">Journal</button><button class="quiet-btn" onclick="newGamePrompt()">New game</button></div></header><div class="layout"><aside class="sidebar"><section class="card profile"><div class="section-label">Your traveler</div><div class="portrait-wrap"><div class="portrait ${state.archetype}" data-mood="${state.mood||'calm'}"><span class="glint"></span></div><span class="portrait-tag">LV. 01</span></div><div class="profile-info"><div class="hero-name">${esc(state.name)}</div><div class="hero-title">${archetypes[state.archetype].label} · ${qualities[state.quality].label}</div></div><div class="trait-line">“${qualities[state.quality].desc}”</div><div class="traits"><span class="trait">${archetypes[state.archetype].label}</span><span class="trait">${qualities[state.quality].label}</span></div></section><section class="card stats"><div class="card-head"><span class="section-label">Attributes</span><span class="score-cap">0—999</span></div>${statMarkup()}<div class="stat-note">Gear bonuses included · checks roll 0—999</div></section><section class="card inventory"><div class="card-head"><span class="section-label">Loadout</span><span class="score-cap">${Object.values(state.gear).filter(Boolean).length} / 3</span></div>${gearMarkup()}</section></aside><main class="main">${content}</main></div></div><div class="toast" id="toast"></div>`}
function setup(){const a=Object.entries(archetypes).map(([key,x])=>`<button class="select-option ${state.archetype===key?'selected':''}" onclick="pick('archetype','${key}')"><b>${x.label}</b><small>${x.desc}</small></button>`).join('');const q=Object.entries(qualities).map(([key,x])=>`<button class="select-option ${state.quality===key?'selected':''}" onclick="pick('quality','${key}')"><b>${x.label}</b><small>${x.desc}</small></button>`).join('');return `<div class="setup-screen"><section class="modal setup-modal"><div class="modal-kicker">A moonlit text adventure</div><h1>The Hollow Bell</h1><p>In a village the world has forgotten, the moon is breaking. Before you descend beneath the shrine, decide who is making the journey. Your choices shape the numbers behind every daring moment.</p><label class="form-label" for="hero-name">What should we call you?</label><input id="hero-name" class="name-input" maxlength="20" placeholder="Aoi" value="${esc(state.name||'')}" autocomplete="off"><span class="form-label">Choose your path</span><div class="option-grid">${a}</div><span class="form-label">And the way you meet the world</span><div class="option-grid">${q}</div><button class="primary wide" onclick="startGame()">Begin the descent&nbsp; →</button><p class="mini-note">Four attributes, each scored from 0 to 999. Equipment changes your odds. Nothing is lost when a roll goes wrong; the story simply takes another shape.</p></section></div>`}
function endingView(){const endings={mercy:{title:'A moon made whole',badge:'THE KINDNESS ENDING',text:`The great wolf presses its forehead to your palm. Its grief pours through you—not as pain, but as rain after a long drought. One by one, the lost memories find their owners. Above Tsukigane, the moon closes its silver seam.\n\nAt dawn, a train arrives at the forgotten station. The wolf waits on the platform beside you, no longer carrying the whole village alone.`},resolve:{title:'The light we set free',badge:'THE RESOLUTE ENDING',text:`Your blade rings once, clear as a bell. The wolf’s antlers crumble into a storm of silver moths; the moon-shard rests in your hands, warm and unbroken. The mountain exhales.\n\nYou return to Tsukigane as the sky pales. No one remembers the wolf, but every doorstep is dusted with bright, impossible moonlight.`},secret:{title:'The song after midnight',badge:'THE SECRET ENDING',text:`The foxfire bell answers your song. The white wolf becomes a thousand blue sparks, swirling upward through the mountain as if the night itself has remembered how to dance.\n\nAt the station, the departure board lights up for the first time in years. A new line appears: <em>Home — now boarding.</em> You laugh, and the moon laughs with you.`}};const d=endings[state.ending]||endings.mercy;return `<div class="eyebrow">The last note</div><span class="ending-badge">${d.badge}</span><h1 class="story-title">${d.title}</h1><div class="scene-art" aria-hidden="true">☾</div><div class="story-copy">${d.text.split('\n\n').map(p=>`<p>${p}</p>`).join('')}</div><p style="font:10px var(--mono);color:#bfa987;margin-top:22px">${esc(state.name)} · ${Object.values(state.gear).filter(Boolean).map(g=>g.name).join(' / ')||'No equipment'} · ${state.step} choices made</p><button class="primary" style="margin-top:12px" onclick="resetGame()">Begin another journey ↻</button>`}
function storyView(){const sc=scenes[state.scene];const dots=Array.from({length:8},(_,i)=>`<span class="progress-dot ${i<Math.min(state.step,8)?'done':''}"></span>`).join('');let body='';if(state.result){const r=state.result;body=`<div class="eyebrow">${r.success?'✦ The moment turns':'✧ The moment passes'}</div><h1 class="story-title">${r.title||'The story moves'}</h1><div class="story-copy">${r.text.split('\n\n').map(p=>`<p>${p}</p>`).join('')}</div>${r.roll!==undefined?`<div class="roll-result ${r.success?'success':'fail'}">${r.statLabel} check · roll <strong>${r.roll}</strong> against <strong>${r.score}</strong> ${r.success?'— success':'— missed by '+(r.roll-r.score)}</div>`:''}${r.reaction?`<div class="equip-reaction">${r.reaction}</div>`:''}<button class="primary" style="margin-top:22px" onclick="continueStory()">${r.ending?'Enter the ending':'Continue'} &nbsp;→</button>`}else if(state.scene==='ending'){body=endingView()}else{body=`<div class="eyebrow">${sc.eyebrow}</div><div class="scene-art" aria-hidden="true">${sc.art}</div><h1 class="story-title">${sc.title}</h1><div class="story-copy">${sc.text.split('\n\n').map(p=>`<p>${p}</p>`).join('')}</div><div class="choices">${sc.choices.map((c,i)=>`<button class="choice" onclick="choose(${i})"><span class="choice-key">0${i+1}</span><span class="choice-text">${c.text}</span><span class="choice-hint">${c.hint||''}</span></button>`).join('')}</div>`}return `<div class="chapter-line"><span class="chapter-no">${String(Math.min(state.step+1,8)).padStart(2,'0')}</span><span class="chapter-rule"></span><span class="chapter-name">${sc?.chapter||'Epilogue · The way home'}</span></div><section class="story-card"><div class="story-inner">${body}</div><div class="story-footer"><span>TSUKIGANE · ${String(state.step+1).padStart(2,'0')}</span><div class="chapter-progress">${dots}</div><span>MOONFALL</span></div></section>`}

