  function choose(index){const sc=scenes[state.scene],c=sc?.choices[index];if(!c||state.result)return;const values=effective(),roll=c.roll?Math.floor(Math.random()*1000):undefined,score=c.roll?values[c.stat]:undefined,success=c.roll?roll<=score:true;let reaction='';const got=c.item||c.gain;if(got&&items[got]){const it=items[got],old=state.gear[it.slot];const oldPower=old?Object.values(old.bonus).reduce((a,b)=>a+b,0):-1,newPower=Object.values(it.bonus).reduce((a,b)=>a+b,0);if(!old||newPower>=oldPower){state.gear[it.slot]=it;reaction=it.reaction;state.mood=got==='moonsteel'||got==='oni'?'determined':'delighted'}else{reaction=`You turn the ${it.name} over in your hands, then tuck it safely away. Your ${old.name} is still the better fit; a pleased little nod crosses your face.`}}
    const text=success?c.pass:c.fail;state.step++;if(c.ending)state.ending=c.ending;state.result={title:success?'A small victory':'The path changes',text,success,roll,score,statLabel:c.stat?statNames[c.stat]:null,reaction,next:c.next,ending:c.next==='ending'};addLog(`${sc.title}: ${text}${reaction?' '+reaction:''}`);save();render()}
  function continueStory(){if(!state.result)return;const r=state.result;state.scene=r.next;state.result=null;if(state.scene==='ending')state.ending=state.ending||'mercy';save();render();window.scrollTo({top:0,behavior:'smooth'})}
  function pick(field,value){if(field==='archetype'||field==='quality')state[field]=value;render();const input=$('#hero-name');if(input)input.focus()}
  function render(){const root=$('#app');if(!state.started)root.innerHTML=setup();else root.innerHTML=layout(storyView())}
  function openJournal(){if(!state.started)return;const entries=state.log.map(e=>`<div class="journal-entry"><span class="journal-time">ENTRY ${String(e.step+1).padStart(2,'0')}</span>${e.text}</div>`).join('')||'<p>Your story is waiting to be written.</p>';document.body.insertAdjacentHTML('beforeend',`<div class="overlay" id="journal" onclick="if(event.target===this)closeJournal()"><section class="modal"><div class="modal-kicker">Notes from the journey</div><h1 style="font-size:35px">Field journal</h1><p>Every choice leaves a mark.</p>${entries}<button class="primary wide" onclick="closeJournal()">Back to the story</button></section></div>`)}
  function closeJournal(){document.querySelector('#journal')?.remove()}
  function newGamePrompt(){if(confirm('Start a new journey? Your current story will be replaced.'))resetGame()}
  function resetGame(){localStorage.removeItem('moonfall-save');Object.assign(state,{started:false,name:'',archetype:'wanderer',quality:'bright',base:{},gear:{weapon:null,charm:null,coat:null},scene:'gate',step:0,log:[],ending:false,result:null,mood:'calm'});render()}
  document.addEventListener('keydown',e=>{if(e.target.matches('input'))return;if(document.querySelector('#journal')){if(e.key==='Escape')closeJournal();return}if(!state.started)return;if(state.result&&(e.key==='Enter'||e.key===' ')){e.preventDefault();continueStory();return}if(state.scene in scenes&&!state.result){const i=Number(e.key)-1;if(i>=0&&i<scenes[state.scene].choices.length)choose(i)}});
  if(!load())state.started=false;render();
</script>

