--- index.html
+++ index.html
@@ -16,9 +16,8 @@
     @media(max-width:850px){.shell{padding:18px 18px 30px}.layout{grid-template-columns:220px minmax(0,1fr);gap:14px}.portrait-wrap{width:105px;height:105px}.story-card{padding:27px;min-height:550px}.scene-art{width:112px;height:112px;font-size:40px}}
     @media(max-width:650px){.shell{padding:12px 12px calc(88px + env(safe-area-inset-bottom))}.topbar{height:36px;margin-bottom:15px}.edition{display:none}.brand{font-size:10px}.layout{display:flex;flex-direction:column-reverse;gap:12px}.main,.sidebar{width:100%}.sidebar{display:grid;grid-template-columns:1fr 1fr;gap:9px}.profile{grid-column:1/-1;display:grid;grid-template-columns:66px 1fr;align-items:center;padding:11px 13px}.profile .section-label{grid-column:1/-1}.portrait-wrap{width:55px;height:55px;margin:8px 0 0}.portrait:before{top:12px;left:14px;width:25px;height:12px;border-top-width:4px}.portrait:after{left:15px;top:25px;font-size:10px;letter-spacing:5px}.portrait .glint{left:25px;top:35px;width:6px}.portrait-tag{font-size:7px;padding:2px 4px}.profile-info{text-align:left;padding-left:9px}.hero-name{text-align:left;font-size:19px}.hero-title{text-align:left;font-size:10px}.trait-line,.traits{display:none}.stats,.inventory{padding:11px}.stats .card-head,.inventory .card-head{margin-bottom:8px}.stat{margin:8px 0}.stat-note{display:none}.equip-row{padding:6px 0;gap:6px}.equip-icon{width:24px;height:24px}.equip-name{font-size:9px}.chapter-line{margin:0 3px 10px}.story-card{padding:22px 18px;min-height:0}.story-title{font-size:30px;margin-bottom:13px}.story-copy{font-size:13px;line-height:1.75}.scene-art{width:82px;height:82px;font-size:30px;margin:0 2px 5px 13px}.scene-art:before{inset:6px}.scene-art:after{inset:-5px}.choices{margin-top:20px;gap:7px}.choice{padding:12px 10px;gap:9px}.choice-hint{display:none}.choice-text{font-size:11px}.story-footer{margin-top:18px}.top-actions .quiet-btn{font-size:10px;padding:6px 9px}.option-grid{grid-template-columns:1fr}.select-option{padding:9px}.select-option b{display:inline;margin-right:8px}.select-option small{font-size:9px}.modal{padding:24px 20px}.modal h1{font-size:36px}}
     @media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important}}
   </style>
-  </style>
 </head>
 <body>
   <div id="app"></div>
   <script>

input.newString:
     function storyView(){const sc=scenes[state.scene];const dots=Array.from({length:8},(_,i)=>`<span class="progress-dot ${i<Math.min(state.step,8)?'done':''}"></span>`).join('');let body='';if(state.result){const r=state.result;body=`<div class="eyebrow">${r.success?'✦ The moment turns':'✧ The moment passes'}</div><h1 class="story-title">${r.title||'The story moves'}</h1><div class="story-copy">${r.text.split('\n\n').map(p=>`<p>${p}</p>`).join('')}</div>${r.roll!==undefined?`<div class="roll-result ${r.success?'success':'fail'}">${r.statLabel} check · roll <strong>${r.roll}</strong> against <strong>${r.score}</strong> ${r.success?'— success':'— missed by '+(r.roll-r.score)}</div>`:''}${r.reaction?`<div class="equip-reaction">${r.reaction}</div>`:''}<button class="primary" style="margin-top:22px" onclick="continueStory()">${r.ending?'Enter the ending':'Continue'} &nbsp;→</button>`}else if(state.scene==='ending'){body=endingView()}else{body=`<div class="eyebrow">${sc.eyebrow}</div><div class="scene-art" aria-hidden="true">${sc.art}</div><h1 class="story-title">${sc.title}</h1><div class="story-copy">${sc.text.split('\n\n').map(p=>`<p>${p}</p>`).join('')}</div><div class="choices">${sc.choices.map((c,i)=>`<button class="choice" onclick="choose(${i})"><span class="choice-key">0${i+1}</span><span class="choice-text">${c.text}</span><span class="choice-hint">${c.hint||''}</span></button>`).join('')}</div>`}return `<div class="chapter-line"><span class="chapter-no">${String(Math.min(state.step+1,8)).padStart(2,'0')}</span><span class="chapter-rule"></span><span class="chapter-name">${sc?.chapter||'Epilogue · The way home'}</span></div><section class="story-card"><div class="story-inner">${body}</div><div class="story-footer"><span>TSUKIGANE · ${String(state.step+1).padStart(2,'0')}</span><div class="chapter-progress">${dots}</div><span>MOONFALL</span></div></section>`}

    function render(){const app=$('#app');if(!app)return;app.innerHTML=state.started?layout(storyView()):setup()}
    function choose(index){const sc=scenes[state.scene];if(!sc||state.result)return;const c=sc.choices[index];if(!c)return;let success=true,roll,score,statLabel='';if(c.stat){const values=effective();score=values[c.stat]||0;roll=Math.floor(Math.random()*1000);success=roll<score;statLabel=statNames[c.stat]}const text=c.stat?(success?c.pass:c.fail):(c.pass||c.fail||'You make your choice, and the story moves forward.');let reaction='';const itemKey=c.item||c.gain;if(itemKey&&items[itemKey]){const item=items[itemKey];if(state.gear[item.slot]!==item){state.gear[item.slot]=item;reaction=item.reaction;state.mood=success?'pleased':'determined'}}else if(c.stat){state.mood=success?'pleased':'wary'}state.step++;state.scene=c.next;state.ending=c.ending||false;state.result={title:success?'Your choice takes root':'The path answers differently',text,success,roll,score,statLabel,reaction,ending:!!c.ending};addLog(`${sc.title}: ${text}${itemKey&&items[itemKey]?' (obtained '+items[itemKey].name+')':''}`);save();render()}
    function continueStory(){if(!state.result)return;if(state.result.ending){state.scene='ending';state.ending=true}state.result=null;save();render();window.scrollTo({top:0,behavior:'smooth'})}
    function openJournal(){const old=$('#journal-overlay');if(old)old.remove();const overlay=document.createElement('div');overlay.id='journal-overlay';overlay.className='setup-screen';overlay.style.zIndex='20';overlay.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="journal-title"><button class="quiet-btn" style="float:right" onclick="document.querySelector('#journal-overlay').remove()" aria-label="Close journal">Close ✕</button><div class="modal-kicker">Your record of the descent</div><h1 id="journal-title">Journey journal</h1><p>${esc(state.name||'Traveler')} · ${state.step} choice${state.step===1?'':'s'} made</p><div style="max-height:48vh;overflow:auto;margin:18px 0">${state.log.length?state.log.map(entry=>`<article style="padding:12px 0;border-top:1px solid #ffffff16"><small style="font:9px var(--mono);color:var(--gold)">STEP ${String(entry.step).padStart(2,'0')}</small><p style="margin:6px 0;color:#d2cfd0;line-height:1.6">${esc(entry.text)}</p></article>`).join(''):'<p class="empty-equip">Your journey has not yet begun.</p>'}</div><button class="primary" onclick="document.querySelector('#journal-overlay').remove()">Return to the story</button></section>`;overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove()});document.body.appendChild(overlay)}
    function newGamePrompt(){if(!state.started){render();return}if(window.confirm('Begin a new journey? Your current progress will be replaced.'))resetGame()}
    function resetGame(){state.started=false;state.name='';state.base={};state.archetype='wanderer';state.quality='bright';state.gear={weapon:null,charm:null,coat:null};state.scene='gate';state.step=0;state.log=[];state.ending=false;state.result=null;state.mood='calm';try{localStorage.removeItem('moonfall-save')}catch(e){}render();window.scrollTo({top:0,behavior:'smooth'})}
    function pick(kind,key){if(kind==='archetype'&&archetypes[key])state.archetype=key;if(kind==='quality'&&qualities[key])state.quality=key;render()}
    try{const saved=JSON.parse(localStorage.getItem('moonfall-save')||'null');if(saved&&saved.started&&archetypes[saved.archetype]&&qualities[saved.quality]&&scenes[saved.scene]||saved?.scene==='ending'){Object.assign(state,saved);state.gear={weapon:null,charm:null,coat:null,...(saved.gear||{})};state.log=Array.isArray(saved.log)?saved.log:[]}}catch(e){}
    render();document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#journal-overlay')?.remove();if(!state.started||state.result||state.scene==='ending'||e.target.matches('input,textarea'))return;if(e.key==='1'||e.key==='2'){e.preventDefault();choose(Number(e.key)-1)}});
  </script>
</body>

    function render(){const app=$('#app');if(!app)return;app.innerHTML=state.started?layout(storyView()):setup()}
    function choose(index){const sc=scenes[state.scene];if(!sc||state.result)return;const c=sc.choices[index];if(!c)return;let success=true,roll,score,statLabel='';if(c.stat){const values=effective();score=values[c.stat]||0;roll=Math.floor(Math.random()*1000);success=roll<score;statLabel=statNames[c.stat]}const text=c.stat?(success?c.pass:c.fail):(c.pass||c.fail||'You make your choice, and the story moves forward.');let reaction='';const itemKey=c.item||c.gain;if(itemKey&&items[itemKey]){const item=items[itemKey];if(state.gear[item.slot]!==item){state.gear[item.slot]=item;reaction=item.reaction;state.mood=success?'pleased':'determined'}}else if(c.stat){state.mood=success?'pleased':'wary'}state.step++;state.scene=c.next;state.ending=c.ending||false;state.result={title:success?'Your choice takes root':'The path answers differently',text,success,roll,score,statLabel,reaction,ending:!!c.ending};addLog(`${sc.title}: ${text}${itemKey&&items[itemKey]?' (obtained '+items[itemKey].name+')':''}`);save();render()}
    function continueStory(){if(!state.result)return;if(state.result.ending){state.scene='ending';state.ending=true}state.result=null;save();render();window.scrollTo({top:0,behavior:'smooth'})}
    function openJournal(){const old=$('#journal-overlay');if(old)old.remove();const overlay=document.createElement('div');overlay.id='journal-overlay';overlay.className='setup-screen';overlay.style.zIndex='20';overlay.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="journal-title"><button class="quiet-btn" style="float:right" onclick="document.querySelector('#journal-overlay').remove()" aria-label="Close journal">Close ✕</button><div class="modal-kicker">Your record of the descent</div><h1 id="journal-title">Journey journal</h1><p>${esc(state.name||'Traveler')} · ${state.step} choice${state.step===1?'':'s'} made</p><div style="max-height:48vh;overflow:auto;margin:18px 0">${state.log.length?state.log.map(entry=>`<article style="padding:12px 0;border-top:1px solid #ffffff16"><small style="font:9px var(--mono);color:var(--gold)">STEP ${String(entry.step).padStart(2,'0')}</small><p style="margin:6px 0;color:#d2cfd0;line-height:1.6">${esc(entry.text)}</p></article>`).join(''):'<p class="empty-equip">Your journey has not yet begun.</p>'}</div><button class="primary" onclick="document.querySelector('#journal-overlay').remove()">Return to the story</button></section>`;overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove()});document.body.appendChild(overlay)}
